from datetime import date, timedelta

def count_workdays(start, end):
    days = 0
    current = start
    while current <= end:
        if current.weekday() < 5:
            days += 1
        current += timedelta(days=1)
    return days

print(count_workdays(date(2026, 1, 1), date(2026, 1, 31)))

def password_score(pwd):
    score = 0
    if len(pwd) >= 8:
        score += 1
    if any(c.isupper() for c in pwd):
        score += 1
    if any(c.isdigit() for c in pwd):
        score += 1
    if any(not c.isalnum() for c in pwd):
        score += 1
    return score

print(password_score("Abc123!@"))

# 定義堆疊類別
class Stack:
    def __init__(self):
        self.items = []

    # 推入元素
    def push(self, item):
        self.items.append(item)

    #彈出元素
    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            return None

    # 檢查堆疊是否為空
    def is_empty(self):
        return len(self.items) == 0

# 主程式
if __name__ == "__main__":
    stack = Stack()
    num = 12345
    # 將數字轉換為字串，以便逐位推入堆疊
    str_num = str(num)
    # 推入堆疊
    for digit in str_num:
        stack.push(digit)

    # 彈出堆疊，並列印反轉的數字
    reverse_num = ""
    while not stack.is_empty():
        reverse_num += stack.pop()
    print("原數字:", num)
    print("反轉後的數字:", int(reverse_num))

# 定義一個抽象類別
class Animal:
    def speak(self):
        pass

# 定義具體類別
class Dog(Animal):
    def speak(self):
        return "汪汪叫"

class Cat(Animal):
    def speak(self):
        return "喵喵叫"

# 定義工廠類別
class AnimalFactory:
    def create_animal(self, animal_type):
        if animal_type == "dog":
            return Dog()
        elif animal_type == "cat":
            return Cat()
        else:
            return None

# 測試工廠類別
factory = AnimalFactory()
dog = factory.create_animal("dog")
cat = factory.create_animal("cat")

